<?php $editando = isset($servicio); ?>
<div class="mb-3"><label class="form-label">Nombre</label><div class="input-icon-wrapper"><i class="fa-solid fa-tag"></i><input type="text" class="form-control" name="nombre" value="<?= $editando ? htmlspecialchars($servicio['nombre_serv']) : '' ?>" placeholder="Nombre del servicio" required></div></div>
<div class="mb-3"><label class="form-label">Código</label><div class="input-icon-wrapper"><i class="fa-solid fa-barcode"></i><input type="text" class="form-control" name="codigo" value="<?= $editando ? htmlspecialchars($servicio['codigo_serv']) : '' ?>" placeholder="Código único" required></div></div>
<div class="mb-3"><label class="form-label">Prioridad</label><div class="input-icon-wrapper"><i class="fa-solid fa-arrow-up-wide-short"></i><select class="form-select" name="prioridad" required><option value="">Seleccione prioridad</option><?php foreach (['NORMAL' => 'Normal', 'ALTA' => 'Alta', 'EMERGENCIA' => 'Emergencia'] as $valor => $texto): ?><option value="<?= $valor ?>" <?= $editando && $servicio['prioridad_serv'] === $valor ? 'selected' : '' ?>><?= $texto ?></option><?php endforeach; ?></select></div></div>
<?php if (!$editando): ?><div class="mb-4"><label class="form-label">Estado</label><div class="input-icon-wrapper"><i class="fa-solid fa-toggle-on"></i><select class="form-select" name="estado" required><option value="">Seleccione estado</option><option value="1">Activo</option><option value="0">Inactivo</option></select></div></div><?php endif; ?>
